/**
 * BetGenius service worker — app-shell caching for instant navigation.
 *
 * Hand-written rather than generated by a Workbox plugin. What this app needs
 * from a service worker is narrow and mostly about what must NOT be cached, and
 * a build-time plugin that precaches "everything Next emitted" would cache the
 * live-data pages by default — exactly the wrong outcome for a livescores site.
 *
 * Three routing rules, in the order the fetch handler applies them:
 *
 *   1. NEVER CACHED — livescores, fixtures, and every /api/ request. A cached
 *      score is a wrong score, and the app already treats these as live-per-
 *      request (see the note on FixtureDetailCache in prisma/schema.prisma).
 *      These bypass the worker entirely and go to the network, so an offline
 *      device gets a normal browser failure rather than a stale scoreline
 *      presented as current.
 *
 *   2. STALE-WHILE-REVALIDATE — the build's static assets (/_next/static/*,
 *      icons, fonts). These are content-hashed and immutable, so serving from
 *      cache first is always correct and the background refresh only ever
 *      populates newly-named files.
 *
 *   3. NETWORK-FIRST, CACHE AS FALLBACK — page navigations. The network wins
 *      whenever it answers, so a reader never sees yesterday's tips while
 *      online; the cache exists so an install that opens on a bad connection
 *      shows the last-seen page (or the offline shell) instead of the browser's
 *      error page. Predictions carry a kickoff and a date on screen, so a
 *      briefly stale page is legible as stale — unlike a live score.
 *
 * Bump CACHE_VERSION to evict everything on the next activation.
 */

// v2: the placeholder icon set under /icons was replaced with the brand pack's
// artwork under the SAME filenames, and /icons/ is served cache-first as
// immutable — without this bump every already-installed client would keep
// showing the old mark on its home screen indefinitely.
const CACHE_VERSION = "v2";
const SHELL_CACHE = `betgenius-shell-${CACHE_VERSION}`;
const RUNTIME_CACHE = `betgenius-runtime-${CACHE_VERSION}`;

/**
 * Precached at install so the very first offline navigation has something to
 * render. Deliberately tiny: the icons and the offline page only. Next's build
 * assets are content-hashed with names this file cannot know, so they are
 * cached on first use by rule 2 instead of being listed here.
 */
const SHELL_ASSETS = ["/offline", "/icons/icon-192.png", "/icons/icon-512.png"];

/** Paths whose responses are never valid to reuse. */
const NEVER_CACHE = [/^\/api\//, /^\/livescores/, /^\/fixtures/, /^\/admin/, /^\/dashboard/];

const isNeverCached = (pathname) => NEVER_CACHE.some((re) => re.test(pathname));

const isStaticAsset = (pathname) =>
  pathname.startsWith("/_next/static/") || pathname.startsWith("/icons/") || /\.(?:css|js|woff2?|png|jpg|svg|ico)$/.test(pathname);

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE);
      // Individually, not addAll: addAll rejects as a unit, so one missing file
      // would leave the worker uninstalled and the app with no offline support
      // at all.
      await Promise.all(SHELL_ASSETS.map((url) => cache.add(url).catch(() => {})));
      // Take over as soon as installed rather than waiting for every tab to
      // close — this worker's caches are versioned, so there is no
      // half-upgraded state to protect against.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k !== SHELL_CACHE && k !== RUNTIME_CACHE).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  // Only GET is cacheable, and only this origin: a cross-origin response
  // (api-sports.io crests, Google avatars) is opaque, so caching it would store
  // a response whose success this worker cannot even inspect.
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (isNeverCached(url.pathname)) return;

  if (isStaticAsset(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request));
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request));
  }
});

async function staleWhileRevalidate(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => cached);
  return cached ?? network;
}

async function networkFirst(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    const response = await fetch(request);
    // Only 200s are stored. Caching a redirect or an error page would pin a
    // logged-out or errored state in front of the reader on the next cold open.
    if (response.ok && response.type === "basic") cache.put(request, response.clone());
    return response;
  } catch {
    return (await cache.match(request)) ?? (await cache.match("/offline")) ?? Response.error();
  }
}
